package main

import (
	"io"
	"strings"
)

const (
	ansiReset   = "\x1b[0m"
	ansiRed     = "\x1b[31m"
	ansiYellow  = "\x1b[33m"
	ansiBlue    = "\x1b[34m"
	ansiMagenta = "\x1b[35m"
	ansiCyan    = "\x1b[36m"
	ansiWhite   = "\x1b[37m"
	ansiGray    = "\x1b[90m"
)

// jsonFormatter is a streaming, byte oriented JSON indenter/colorizer.
// It never buffers: every byte received is handled immediately so that
// streamed responses can be followed live.
type jsonFormatter struct {
	out     io.Writer
	pretty  bool
	started bool // first byte seen
	raw     bool // passthrough mode (input does not start with { or [)

	depth       int
	inString    bool
	prev        byte
	expectValue bool // a ':' was seen at the current level: strings are values
	pending     bool // the next literal starts a value and must be colored
}

func newJSONFormatter(out io.Writer, pretty bool) *jsonFormatter {
	return &jsonFormatter{out: out, pretty: pretty}
}

func indent(n int) string {
	if n <= 0 {
		return ""
	}
	return strings.Repeat("    ", n)
}

func (f *jsonFormatter) Write(p []byte) (int, error) {
	if !f.pretty {
		return f.out.Write(p)
	}
	var b strings.Builder
	for _, c := range p {
		if !f.started {
			f.started = true
			if c != '{' && c != '[' {
				f.raw = true
			}
		}
		if f.raw {
			b.WriteByte(c)
			continue
		}
		f.handle(&b, c)
		f.prev = c
	}
	if b.Len() > 0 {
		if _, err := io.WriteString(f.out, b.String()); err != nil {
			return 0, err
		}
	}
	return len(p), nil
}

func (f *jsonFormatter) handle(b *strings.Builder, c byte) {
	if f.prev == '\\' {
		// escaped character: copy verbatim
		b.WriteByte(c)
		return
	}
	if f.inString {
		switch c {
		case '"':
			f.inString = false
		case ':':
			f.pending = true
		case ',', '{', '[', '}', ']':
			f.pending = false
		}
		b.WriteByte(c)
		return
	}
	switch c {
	case '{', '[':
		b.WriteString(ansiWhite)
		b.WriteByte(c)
		b.WriteByte('\n')
		f.depth++
		b.WriteString(indent(f.depth))
		f.expectValue = false
		f.pending = false
	case '}', ']':
		if f.depth > 0 {
			f.depth--
		}
		b.WriteByte('\n')
		b.WriteString(indent(f.depth))
		b.WriteString(ansiWhite)
		b.WriteByte(c)
		if f.depth == 0 {
			b.WriteByte('\n')
			b.WriteString(ansiReset)
		}
		f.pending = false
	case ',':
		b.WriteString(ansiWhite)
		b.WriteByte(c)
		b.WriteByte('\n')
		b.WriteString(indent(f.depth))
		f.expectValue = false
		f.pending = false
	case ':':
		b.WriteString(ansiWhite)
		b.WriteString(": ")
		f.expectValue = true
		f.pending = true
	case '"':
		f.inString = true
		if f.expectValue {
			b.WriteString(ansiCyan)
		} else {
			b.WriteString(ansiBlue)
		}
		b.WriteByte(c)
		f.pending = false
	case ' ', '\t', '\n', '\r':
		// insignificant whitespace is dropped and regenerated
	default:
		if f.pending {
			if c == 'n' || c == 't' || c == 'f' {
				b.WriteString(ansiMagenta)
			} else {
				b.WriteString(ansiCyan)
			}
			f.pending = false
		}
		b.WriteByte(c)
	}
}
EOF
echo ok"}

